-- 1c. The count gate
-- READ-ONLY
--
-- GENERATED from 590-proquest-ebc-batch-removal/README.md by tools/Build-SolutionDocs.ps1.
-- Do not edit this file - edit the README and re-run the script.
-- The README carries the reasoning, review gates and caveats.

SELECT
    COUNT(*)                AS [bibs],
    SUM(d.has_ebc)          AS [with_ebc_035],
    COUNT(*) - SUM(d.has_ebc) AS [without_ebc_035],
    SUM(d.items)            AS [items_deleted_by_k]
FROM (
    SELECT
        CASE WHEN EXISTS (
                SELECT 1 FROM bib e
                WHERE e.[bib#] = bc.[bib#]
                  AND e.tag = '035'
                  AND e.text COLLATE Latin1_General_CS_AS LIKE '%EBC[0-9]%')
             THEN 1 ELSE 0 END                               AS has_ebc,
        (SELECT COUNT(*) FROM item i WHERE i.[bib#] = bc.[bib#]) AS items
    FROM bib_control bc
    WHERE bc.create_user = 'CATALOGER'
      AND bc.create_date = DATEDIFF(day, '1970-01-01', '2026-10-26')
      AND EXISTS (
            SELECT 1 FROM bib p
            WHERE p.[bib#] = bc.[bib#]
              AND p.tag = '590'
              AND p.text LIKE '%ProQuest%')
) d;
